{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'shipping spans' what, (SELECT count(*) FROM normal_traces WHERE service_name='shipping') normal_n, (SELECT count(*) FROM abnormal_traces WHERE service_name='shipping') abnormal_n",
          "claim": "Shipping emitted 6 spans in the normal window and zero in the abnormal window."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, time::VARCHAR t, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name='shipping-5fb88795b7-th5n9' ORDER BY time LIMIT 5",
          "claim": "Shipping pod restart counter was already 1 at the start of the abnormal window, versus 0 in normal."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, count(*) n, max(time)::VARCHAR last_log FROM normal_logs WHERE service_name='shipping' GROUP BY 1 UNION ALL SELECT service_name, count(*), max(time)::VARCHAR FROM abnormal_logs WHERE service_name='shipping' GROUP BY 1",
          "claim": "Shipping logs stop at the abnormal window start (09:19:50) and never resume through 09:24:49."
        }
      ]
    },
    {
      "service": "frontend",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('dns.lookup','grpc.oteldemo.ProductReviewService/GetProductReviews','grpc.oteldemo.ProductReviewService/AskProductAIAssistant') GROUP BY ALL ORDER BY 2",
          "claim": "Frontend dns.lookup spans error, and every product-review gRPC call from frontend errors in under 0.5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%product-reviews%' OR (service_name='frontend' AND span_name='GET' AND attr_http_response_status_code=500) GROUP BY ALL",
          "claim": "Product-review requests through frontend return HTTP 500, while other frontend traffic stays 200."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('HTTP POST','oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL",
          "claim": "Checkout's HTTP POST calls to shipping fail (9 errors), and PlaceOrder returns errors as a result."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE span_name='POST /api/checkout' GROUP BY ALL",
          "claim": "Frontend POST /api/checkout returns HTTP 500 for every checkout attempt in the abnormal window."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_http_response_status_code=500 GROUP BY ALL",
          "claim": "Frontend-proxy ingress and egress spans return HTTP 500 for the failing frontend requests."
        }
      ]
    }
  ]
}
